"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[4543],{84708:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/MARSLib/docs/intro","label":"Tutorials Directory","docId":"intro","unlisted":false},{"type":"category","label":"Tutorials","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Onboarding & Setup","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/MARSLib/docs/tutorials/setup/getting-started","label":"Software Setup & Git","docId":"tutorials/setup/getting-started","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/setup/telemetry","label":"Telemetry Mastery","docId":"tutorials/setup/telemetry","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/setup/ci","label":"Intro to CI/CD & Testing","docId":"tutorials/setup/ci","unlisted":false}]},{"type":"category","label":"Zero-to-Hero (Start Here)","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/MARSLib/docs/tutorials/zero-to-hero/landscape","label":"1. The Dev Ecosystem","docId":"tutorials/zero-to-hero/landscape","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/zero-to-hero/hardware","label":"2. The Hardware Paradigm","docId":"tutorials/zero-to-hero/hardware","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/zero-to-hero/command-based","label":"3. Command-Based Paradigm","docId":"tutorials/zero-to-hero/command-based","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/zero-to-hero/control-basics","label":"4. Control Theory Crash Course","docId":"tutorials/zero-to-hero/control-basics","unlisted":false}],"href":"/MARSLib/docs/category/zero-to-hero-start-here"},{"type":"category","label":"Framework Mastery","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/MARSLib/docs/tutorials/framework/io-layer","label":"The IO Layer Pattern","docId":"tutorials/framework/io-layer","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/swerve","label":"High-Frequency Swerve","docId":"tutorials/framework/swerve","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/state-machines","label":"State Machine Logic","docId":"tutorials/framework/state-machines","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/zero-allocation","label":"Strict Zero-Allocation","docId":"tutorials/framework/zero-allocation","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/simulation","label":"Physics-First Development","docId":"tutorials/framework/simulation","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/vision","label":"Vision Fusion & Filtration","docId":"tutorials/framework/vision","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/control-theory","label":"Control Theory Mastery","docId":"tutorials/framework/control-theory","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/architecture","label":"Core Architecture","docId":"tutorials/framework/architecture","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/pathfinding","label":"Pathfinding & Autonomous","docId":"tutorials/framework/pathfinding","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/fault-resilience","label":"Fault Resilience","docId":"tutorials/framework/fault-resilience","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/sysid","label":"Continuous SysId","docId":"tutorials/framework/sysid","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/framework/sotm","label":"Shooting On The Move","docId":"tutorials/framework/sotm","unlisted":false}]},{"type":"category","label":"The Elite Playbook","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/MARSLib/docs/tutorials/elite/power-shedding","label":"Dynamic Power Shedding","docId":"tutorials/elite/power-shedding","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/elite/code-mining","label":"Elite Architecture Mining","docId":"tutorials/elite/code-mining","unlisted":false},{"type":"link","href":"/MARSLib/docs/tutorials/elite/uploader","label":"Automated Log Uploader","docId":"tutorials/elite/uploader","unlisted":false}]}],"href":"/MARSLib/docs/category/tutorials"},{"type":"category","label":"AI Agents & Skills","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/MARSLib/docs/agent-skills/intro","label":"MARSLib AI Skills","docId":"agent-skills/intro","unlisted":false},{"type":"link","href":"/MARSLib/docs/agent-skills/ide-setup","label":"IDE Integration Guide","docId":"agent-skills/ide-setup","unlisted":false}],"href":"/MARSLib/docs/category/ai-agents--skills"},{"type":"link","href":"/MARSLib/docs/resources","label":"External Resources","docId":"resources","unlisted":false}]},"docs":{"agent-skills/ide-setup":{"id":"agent-skills/ide-setup","title":"IDE Integration Guide","description":"MARSLib\'s .agent markdown framework is naturally agnostic, meaning the skills can integrate into whatever AI workflow your programming team prefers.","sidebar":"tutorialSidebar"},"agent-skills/intro":{"id":"agent-skills/intro","title":"MARSLib AI Skills","description":"MARSLib is the world\'s first FRC software framework specifically architected for Agentic Co-Development.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Tutorials Directory","description":"Zero-to-Hero (Start Here)","sidebar":"tutorialSidebar"},"resources":{"id":"resources","title":"External Resources","description":"MARSLib is built to strictly interface with the industry-standard components in the FIRST Robotics Competition ecosystem. We extend our deepest gratitude to these framework providers and recommend reading their core documentation:","sidebar":"tutorialSidebar"},"tutorials/elite/code-mining":{"id":"tutorials/elite/code-mining","title":"Elite Architecture Mining","description":"Every year, Chief Delphi lights up with the source code drops from World Champions like Team 1690, 254, 6328, and 2910. Every year, hundreds of teams attempt to copy-paste their advanced time-of-flight models or trajectory solvers. And every year, their robots break due to architectural bloat and corrupted state variables.","sidebar":"tutorialSidebar"},"tutorials/elite/power-shedding":{"id":"tutorials/elite/power-shedding","title":"Dynamic Power Shedding","description":"Modern FRC hardware\u2014specifically Krakens and Falcons\u2014can physically pull more power than the RoboRIO and a 12V battery can safely provide. If your Swerve Drive engages in a massive pushing match while the Intake is stalled on a stuck Fuel Ball, the battery voltage will dip below 7V, the RoboRIO will reset, and you will lose the match.","sidebar":"tutorialSidebar"},"tutorials/elite/uploader":{"id":"tutorials/elite/uploader","title":"Automated Log Uploader","description":"Manually retrieving USB drives from the RoboRIO is tedious. MARSLib introduces the LogUploader, an asynchronous daemon thread that quietly runs in the background. If it detects a tethered internet connection, it automatically pushes all new AdvantageKit .wpilog files directly to your team\'s GitHub repository!","sidebar":"tutorialSidebar"},"tutorials/framework/architecture":{"id":"tutorials/framework/architecture","title":"Core Architecture","description":"MARSLib is designed with a strict zero-allocation abstraction layer. The framework shields deterministic physics processing and automated logging from the hardware implementations to guarantee consistency across physical and simulated robots.","sidebar":"tutorialSidebar"},"tutorials/framework/control-theory":{"id":"tutorials/framework/control-theory","title":"Control Theory Mastery","description":"Basic PID loops are reacting to the past. To achieve World Championship fidelity, your mechanisms must predict the future. MARSLib employs advanced control theory algorithms, including Feedforwards and State Space Models.","sidebar":"tutorialSidebar"},"tutorials/framework/fault-resilience":{"id":"tutorials/framework/fault-resilience","title":"Fault Resilience","description":"Fault Resilience","sidebar":"tutorialSidebar"},"tutorials/framework/io-layer":{"id":"tutorials/framework/io-layer","title":"The IO Layer Pattern","description":"The most important architectural rule in MARSLib is the separation of hardware from logic. We use the AdvantageKit IO abstraction pattern to ensure that our robot code is deterministic, testable, and capable of bit-perfect log replay.","sidebar":"tutorialSidebar"},"tutorials/framework/pathfinding":{"id":"tutorials/framework/pathfinding","title":"Pathfinding & Autonomous","description":"To win on Einstein, a robot cannot simply drive straight lines from point A to point B in the autonomous period. The field is littered with obstacles, standard trajectories lack fluidity, and sudden game piece collisions require dynamic recalculations. MARSLib integrates deeply with PathPlanner to bring seamless, holistic pathfinding to the FRC field.","sidebar":"tutorialSidebar"},"tutorials/framework/simulation":{"id":"tutorials/framework/simulation","title":"Physics-First Development","description":"Waiting for a physical robot to be built is the #1 cause of losing FRC competitions. MARSLib uses Dyn4j, a 2D physics engine, to create a high-fidelity virtual world where you can develop 100% of your code before the metal is even cut.","sidebar":"tutorialSidebar"},"tutorials/framework/sotm":{"id":"tutorials/framework/sotm","title":"Shooting On The Move","description":"Stopping the robot to aim is a 2-second penalty on your cycle time. In modern high-level play, the robot must be capable of calculating a solution and firing while traversing the field at 4+ m/s. MARSLib uses a high-fidelity Iterative Kinematic Solver to find these solutions in real-time.","sidebar":"tutorialSidebar"},"tutorials/framework/state-machines":{"id":"tutorials/framework/state-machines","title":"State Machine Logic","description":"Coordinating multiple mechanisms (like an intake, a pivot, and a shooter) is incredibly complex. If you use simple if-statements, you\'ll eventually end up with \\"spaghetti code\\" where the robot crashes into itself. MARSLib uses MARSStateMachine within the overarching MARSSuperstructure to manage these transitions safely.","sidebar":"tutorialSidebar"},"tutorials/framework/swerve":{"id":"tutorials/framework/swerve","title":"High-Frequency Swerve","description":"A standard FRC robot executes its control loop every 20ms (50Hz). This is fine for moving an elevator, but it is unacceptably slow for Swerve Odometry. If a robot moving at 5 m/s only calculates its position 50 times a second, the math inherently creates a \\"drift\\" of several centimeters per second.","sidebar":"tutorialSidebar"},"tutorials/framework/sysid":{"id":"tutorials/framework/sysid","title":"Continuous SysId","description":"Static System Identification (running specific \\"quasistatic\\" tests in the pits) is the industry standard. However, mechanism friction changes as the robot\'s gears wear down or get dirty throughout a 3-day competition. MARSLib introduces Continuous SysId, which passively identifies your kV and kA constants during real matches.","sidebar":"tutorialSidebar"},"tutorials/framework/vision":{"id":"tutorials/framework/vision","title":"Vision Fusion & Filtration","description":"In the FRC 2026: REBUILT game, absolute field localization is critical. MARSLib\'s MARSVision subsystem combines data from multiple cameras and strictly filters out \\"hallucinations\\" using techniques pioneered by elite teams. We utilize AprilTags as the primary landmarks for global pose estimation.","sidebar":"tutorialSidebar"},"tutorials/framework/zero-allocation":{"id":"tutorials/framework/zero-allocation","title":"Strict Zero-Allocation","description":"In high-frequency robotics (250Hz+), the #1 cause of sudden, non-deterministic jitter is the Java Garbage Collector (GC). Every time you use the new keyword inside a loop, you are creating a tiny bit of \\"trash\\" that the CPU eventually has to stop everything and clean up.","sidebar":"tutorialSidebar"},"tutorials/setup/ci":{"id":"tutorials/setup/ci","title":"Intro to CI/CD & Testing","description":"If you\'re new to software engineering, you might think the only way to know if your code works is to put the robot on a carpet, cross your fingers, and hit \\"Enable\\". In reality, the professional software industry\u2014and MARSLib\u2014uses a system called CI/CD to guarantee our code is safe before we ever touch the physical machine.","sidebar":"tutorialSidebar"},"tutorials/setup/getting-started":{"id":"tutorials/setup/getting-started","title":"Software Setup & Git","description":"Before you can begin programming the robot, you need to configure your local development environment. MARSLib uses industry-standard tooling alongside specific WPILib architecture to deploy its advanced zero-allocation simulations. Follow these steps meticulously to get started. Note this is still a work in progress.","sidebar":"tutorialSidebar"},"tutorials/setup/telemetry":{"id":"tutorials/setup/telemetry","title":"Telemetry Mastery","description":"Driving blindly is a thing of the past. In MARSLib, we use Mechanical Advantage\'s AdvantageKit, which guarantees a structurally clean decoupling of hardware states, ensuring deterministic Replay of any past FRC match. All of this telemetry data is then visualized dynamically in AdvantageScope.","sidebar":"tutorialSidebar"},"tutorials/zero-to-hero/command-based":{"id":"tutorials/zero-to-hero/command-based","title":"3. Command-Based Paradigm","description":"If you\'ve built simple robots before, you might have written all your code linearly: \\"Wait 2 seconds, drive forward, spin the intake, stop.\\" In FRC, this is lethal. Blocking the main thread for even a single second violates the FRC networking envelope and crashes the robot.","sidebar":"tutorialSidebar"},"tutorials/zero-to-hero/control-basics":{"id":"tutorials/zero-to-hero/control-basics","title":"4. Control Theory Crash Course","description":"If you tell an elevator motor, \\"Go up at 6 Volts,\\" when does it know to stop? If it reaches the target and instantly cuts voltage to zero, gravity will pull the heavy elevator right back down. We need Closed-Loop Control.","sidebar":"tutorialSidebar"},"tutorials/zero-to-hero/hardware":{"id":"tutorials/zero-to-hero/hardware","title":"2. The Hardware Paradigm","description":"To program a physical FRC mechanism effectively, you must understand the constraints of the electrical signals traveling exactly underneath your code. In FRC, code doesn\'t just run; it actively bridges power systems and data packets.","sidebar":"tutorialSidebar"},"tutorials/zero-to-hero/landscape":{"id":"tutorials/zero-to-hero/landscape","title":"1. The Dev Ecosystem","description":"Before we touch a single line of Java or look at a physical robot, you must understand the toolchain we use to build, track, and deploy code. FRC development is uniquely complex because it relies heavily on offline-capable environments and cross-platform utilities.","sidebar":"tutorialSidebar"}}}}')}}]);